<script setup lang="ts">
import {localize} from './localization';

import {partName} from '../../../packages/reference/body-parts';
import {computed,ref} from 'vue';
import {useSession} from './store';
const props=defineProps<{language:'zh'|'en'}>(),emit=defineEmits<{select:[id:string]}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const markings=computed(()=>(store.data.project?.markings??[]).filter(m=>m.surfaceId===store.data.project?.surface?.id)),allLocked=computed(()=>!!markings.value.length&&markings.value.every(m=>m.locked)),confirmClear=ref(false);
async function lockAll(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'markings.lockAll',locked:!allLocked.value}));}
async function clearAll(){const p=store.data.project;if(p&&await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'markings.clear'})))confirmClear.value=false;}
async function deleteMarking(markingId:string){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'marking.delete',markingId}));}
async function review(markingId:string,reviewed:boolean){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'marking.review',markingId,reviewed}));}

</script>
<template><section class="projection-panel"><strong>{{zh?'已贴附花纹':localize('Attached markings')}}</strong><p>{{zh?'从左侧共享花纹抽屉选择来源并贴附，可在展开前完成。下面管理已贴附花纹及跨片 UV 编辑。':localize('Attach sources from the shared drawer before unwrapping; manage markings and UV edits below.')}}</p><div v-if="markings.length" class="mapping-final-actions"><p>{{zh?'调整完成后旋转检查整个模型，再一次确认并锁定全部花纹。':localize('After adjusting, rotate and inspect the whole model, then approve and lock all markings together.')}}</p><button :disabled="store.busy" @click="lockAll">{{allLocked?(zh?'解锁全部贴附花纹':localize('Unlock all attached markings')):(zh?'确认并锁定全部贴附花纹':localize('Approve and lock all attached markings'))}}</button><button :disabled="store.busy" @click="confirmClear=!confirmClear">{{zh?'清空模型贴附花纹':localize('Clear model markings')}}</button><div v-if="confirmClear" role="alert"><p>{{zh?'仅移除当前模型上的全部贴附花纹；源花纹库和已有裁切版本保留，可撤销恢复。':localize('Remove all markings from this model. Source patterns and saved cutting versions remain; undo restores the markings.')}}</p><button :disabled="store.busy" @click="clearAll">{{zh?'确认清空贴附花纹':localize('Confirm clear markings')}}</button><button @click="confirmClear=false">{{zh?'取消':localize('Cancel')}}</button></div></div><div v-for="m in markings" :key="m.id" :data-marking-id="m.id"><strong>{{m.name}}</strong><span v-if="m.placement" class="auto-status"> · {{partName(m.placement.part,zh)}} · {{m.placement.reviewed?(zh?'自动位置已确认':localize('Automatic position approved')):(zh?'自动位置待确认':localize('Automatic position needs review'))}}</span><template v-if="m.inference"><span class="inferred-status">{{m.inference.reviewed?(zh?'推断 · 已审核':localize('Inferred · reviewed')):(zh?'推断 · 待审核，禁止导出':localize('Inferred · review required, export blocked'))}}</span><button :disabled="store.busy||m.locked" @click="review(m.id,!m.inference.reviewed)">{{m.inference.reviewed?(zh?'撤回审核':localize('Withdraw review')):(zh?'已检查，确认补全':localize('Approve inspected completion'))}}</button></template><span v-if="m.locked">{{zh?'已锁定':localize('Locked')}}</span> · {{m.fragments.length}} faces / {{m.paths.length}} pieces <button v-for="path in m.paths" :key="path.pieceId" @click="emit('select',path.pieceId)">{{store.data.project?.pieces.find(p=>p.id===path.pieceId)?.name}}</button><button :disabled="store.busy||m.locked" @click="deleteMarking(m.id)">{{zh?'删除花纹':localize('Delete marking')}}</button></div></section></template>
<style scoped>.projection-panel{padding-top:10px}p{font-size:11px;line-height:1.7}button{width:100%;white-space:normal;margin-block:5px}</style>
